send() { tmux send-keys -t "$1" -l "$2"; tmux send-keys -t "$1" C-m; }
MSG="Khiem, 12:35 UTC: stop holding for Z. The judge emulator is only needed for the oracle, no-cache and echo probes (GATE-V2 3.1). Everything else in gate v2 runs without it and you can start now on your owned tasks in claim order, one task at a time, under BUDGET: (1) the class K sentence in instruction.md and tests/task_prompt.txt for every xlsx deliverable (3.3 K, exact wording there), snapshot to _before/ and log in FIX-LOG; (2) the blind Opus Comprehensive Review with the maps from 3.2: criterion-to-instruction with the tightened token rule (a), golden-claim-to-source (b), quantifier (c), reliability (d); write GATE.md with the map results; (3) fixes per 3.3 for what the maps find; (4) the existing scans in /root/qc/tools/ (rewardkit_pin, metadata_fill, env_size_report, golden_citation_scan, instruction_input_scan, cross_group_duplicate_scan) on each task. When judge_emulate.py is cleared by main, run the three probes and complete GATE.md. Nothing zips before all of 3.4 holds; that is the only thing waiting on Z. Also new: 25-4-0, 53-0-0, 53-5-0 are back (14 of 15, 0 accept); GATE-V2 1c lands in a few minutes with three more patterns, read it when it appears. Update your STATUS file with the task you are on."
for s in B D E F; do send "$s" "$MSG"; done
echo sent
